int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (strcmp(fe->ops.tuner_ops.info.name, cfg->firmware_name) != 0) {
        if (fe->tuner_priv) {
            kfree(fe->tuner_priv);
            fe->tuner_priv = NULL;
        }

        fe->tuner_priv = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->tuner_priv) {
            mutex_unlock(&fe->lock);
            return -ENOMEM;
        }
    }

    if (!fe->tuner_priv && cfg->firmware_name) {
        fe->tuner_priv = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->tuner_priv) {
            mutex_unlock(&fe->lock);
            return -ENOMEM;
        }
    }

    if (cfg->state == XC2028_NO_FW_LOADED) {
        result = request_firmware_nowait(NULL, 1, fe->tuner_priv, fe->dvb->adapter->num, &fe->dvb->adapter->device, &cfg->firmware_load_complete, NULL);
        if (result < 0) {
            kfree(fe->tuner_priv);
            fe->tuner_priv = NULL;
            mutex_unlock(&fe->lock);
            return result;
        }
    }

    mutex_unlock(&fe->lock);
    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (strcmp(fe->ops.tuner_ops.set_config.firmware_name, cfg->firmware_name) != 0) {
