int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *priv = fe->demodulator_priv;
    struct xc2028_config *config = (struct xc2028_config *)priv_cfg;
    int ret = 0;

    mutex_lock(&priv->lock);

    if (strcmp(priv->firmware_name, config->firmware_name) != 0) {
        kfree(priv->firmware_name);
        priv->firmware_name = kstrdup(config->firmware_name, GFP_KERNEL);
        if (!priv->firmware_name) {
            ret = -ENOMEM;
            goto error;
        }

        if (priv->firmware) {
            release_firmware(priv->firmware);
            priv->firmware = NULL;
        }
    }

    if (!priv->firmware && priv->state == XC2028_STATE_NO_FIRMWARE) {
        ret = request_firmware_nowait(THIS_MODULE, 1, priv->firmware_name, fe->dvb->priv, GFP_KERNEL, priv, &xc2028_fw_cb);
        if (ret) {
            goto error;
        }
    }

    priv->config = *config;

    mutex_unlock(&priv->lock);
    return ret;

error:
    mutex_unlock(&priv->lock);
    return ret;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (fe->ops.release) {
        kfree(fe->ops.release);
        fe->ops.release = NULL;
    }

    if (strncmp(fe->ops.firmware_name, cfg->firmware_name, sizeof(fe->ops.firmware_name)) != 0) {
        if (fe->ops.firmware_name) {
            kfree(fe->ops.firmware_name);
        }
        fe->ops.firmware_name = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->ops.firmware_name) {
            result = -ENOMEM;
            goto unlock_mutex;
        }
    }

    if (!fe->ops.firmware_name) {
        result = request_firmware_nowait(NULL, 0, fe->ops.firmware_name,
                                         fe->dvb->adapter->num, fe->dvb, NULL);
        if (result < 0)
            goto unlock_mutex;
    }

unlock_mutex:
    mutex_unlock(&fe->lock);
    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (fe->ops.tuner_ops.set_config)
        fe->ops.tuner_ops.set_config(fe, priv_cfg);

    if (strcmp(cfg->firmware_name, fe->dvb->priv) != 0) {
        kfree(fe->dvb->priv);
        fe->dvb->priv = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->dvb->priv) {
            mutex_unlock(&fe->lock);
            return -ENOMEM;
        }
    }

    if (fe->state == 0) {
        result = request_firmware_nowait(fe->dvb->priv, 0,
                                         fe->dvb->priv,
                                         &fe->dvb->dev, GFP_KERNEL,
                                         (void *)cfg, NULL);
    }

    mutex_unlock(&fe->lock);
    return result;
}
